with deduped as (select * from (select *, row_number() over (partition by brand order by price, id) as rn from products) ranked where rn = 1) select s.id, s.product_name, s.brand, s.price, s.cost, s.launch_date, s.tags, s.supplier_id, case when product_name rlike '^(Running Shoes|Desk Lamp)$' then 'GROUP_B' else 'OTHER_ZONE' end as product_name_zone, (select min(t2.cost) from products t2 where t2.supplier_id = s.supplier_id) as min_product_cost from deduped s order by product_name_zone desc nulls first;
